function renderScatterPlot(container, data, options = {}) {
  const {
    width = 450,
    height = 300,
    margin: customMargin = {},
    defaultRadius = 5,
    color = 'steelblue',
    onSelectPoint,
  } = options;

  const margin = Object.assign({ top: 20, right: 20, bottom: 40, left: 40 }, customMargin);
  const innerWidth = Math.max(0, width - margin.left - margin.right);
  const innerHeight = Math.max(0, height - margin.top - margin.bottom);

  container.innerHTML = '';

  const svg = d3
    .select(container)
    .append('svg')
    .attr('width', width)
    .attr('height', height);

  const g = svg
    .append('g')
    .attr('class', 'chart-area')
    .attr('transform', `translate(${margin.left}, ${margin.top})`);

  const points = Array.isArray(data) ? data : [];
  const xExtent = d3.extent(points, (d) => d.x);
  const yExtent = d3.extent(points, (d) => d.y);

  const xDomain = xExtent[0] !== undefined && xExtent[1] !== undefined ? xExtent : [0, 1];
  const yDomain = yExtent[0] !== undefined && yExtent[1] !== undefined ? yExtent : [0, 1];

  const xScale = d3
    .scaleLinear()
    .domain(xDomain)
    .nice()
    .range([0, innerWidth]);

  const yScale = d3
    .scaleLinear()
    .domain(yDomain)
    .nice()
    .range([innerHeight, 0]);

  g.append('g')
    .attr('class', 'x-axis')
    .attr('transform', `translate(0, ${innerHeight})`)
    .call(d3.axisBottom(xScale));

  g.append('g')
    .attr('class', 'y-axis')
    .call(d3.axisLeft(yScale));

  g.selectAll('circle.scatter-dot')
    .data(points)
    .join('circle')
    .attr('class', 'scatter-dot')
    .attr('cx', (d) => xScale(d.x))
    .attr('cy', (d) => yScale(d.y))
    .attr('r', (d) => d.radius || defaultRadius)
    .attr('fill', color)
    .on('click', function (_, d) {
      if (typeof onSelectPoint === 'function') {
        const index = points.indexOf(d);
        onSelectPoint(d, index >= 0 ? index : 0);
      }
    });

  return {
    svg: svg.node(),
    destroy() {
      svg.remove();
      container.innerHTML = '';
    },
  };
}

