  container.innerHTML = '';

  const width = options.width ?? 480;
  const height = options.height ?? 260;
  const scaleExtent = options.scaleExtent ?? [1, 8];
  const color = options.color ?? 'steelblue';
  const margin = { top: 15, right: 20, bottom: 25, left: 40 };

