      xAxisGroup.call(d3.axisBottom(newXScale));
      circles.attr('cx', d => newXScale(d.x));
      if (typeof options.onZoomChange === 'function') {
        options.onZoomChange({
          k: transform.k,
          x: transform.x,
          y: transform.y,
        });
