    .selectAll('line.graph-link')
    .data(links)
    .join('line')
    .attr('class', 'graph-link')
    .attr('stroke', 'slategray')
    .attr('stroke-opacity', '0.6')
    .attr('stroke-width', '1.5');

  const dragBehavior = d3
    .drag<SVGCircleElement, ForceGraphNode>()
    .on('start', (event, d) => {
      if (!event.active) simulation.alphaTarget(0.3).restart();
      d.fx = d.x;
      d.fy = d.y;
    })
    .on('drag', (event, d) => {
      d.fx = event.x;
      d.fy = event.y;
    })
    .on('end', (event, d) => {
      if (!event.active) simulation.alphaTarget(0);
      d.fx = null;
      d.fy = null;
    });

  const nodeElements = nodesLayer
    .selectAll('circle.graph-node')
    .data(nodes)
    .join('circle')
    .attr('class', 'graph-node')
    .attr('r', nodeRadius)
    .attr('fill', 'steelblue')
    .attr('stroke', 'white')
    .attr('stroke-width', '1.5')
    .call(dragBehavior)
    .on('click', (event, d) => {
      if (typeof options.onNodeClick === 'function') {
        options.onNodeClick(d);
      }
    });

  simulation.on('tick', () => {
    linkElements
      .attr('x1', (d: any) => d.source.x)
      .attr('y1', (d: any) => d.source.y)
      .attr('x2', (d: any) => d.target.x)
      .attr('y2', (d: any) => d.target.y);

    nodeElements
      .attr('cx', d => d.x ?? 0)
      .attr('cy', d => d.y ?? 0);
  });

  return {
    svg: svg.node() as SVGSVGElement,
    simulation,
    getNodes: () => simulation.nodes(),
    getLinks: () => {
      const linkForce = simulation.force('link');
      return linkForce ? (linkForce.links() as ForceGraphLink[]) : links;
    },
    pinNode: (id: string, x: number, y: number) => {
      const node = simulation.nodes().find(n => n.id === id);
      if (node) {
        node.fx = x;
        node.fy = y;
        simulation.alpha(0.1).restart();
      }
    },
    unpinNode: (id: string) => {
      const node = simulation.nodes().find(n => n.id === id);
      if (node) {
        node.fx = null;
        node.fy = null;
        simulation.alpha(0.1).restart();
      }
    },
    destroy: () => {
      simulation.stop();
      svg.remove();
      container.innerHTML = '';
    },
  };
}

